const fs = require('fs');
const path = require('path');

const filesToInspect = [
  'edits-Purchase.jsx.json',
  'edits-purchase.js.json',
  'edits-CSAMyInvoices.jsx.json',
  'edits-CSAMyPurchase.jsx.json',
  'edits-CSAMyBilling.jsx.json'
];

function inspect() {
  for (const filename of filesToInspect) {
    const filePath = path.join(__dirname, filename);
    if (!fs.existsSync(filePath)) {
      console.log(`File ${filename} does not exist.`);
      continue;
    }
    const data = JSON.parse(fs.readFileSync(filePath, 'utf-8'));
    console.log(`\n======================================================`);
    console.log(`=== File: ${filename} (Total edits: ${data.length}) ===`);
    console.log(`======================================================`);

    data.forEach((edit, idx) => {
      console.log(`\n[Edit #${idx + 1}] Step: ${edit.step_index} | Type: ${edit.name}`);
      if (edit.name === 'replace_file_content') {
        console.log(`StartLine: ${edit.args.StartLine} | EndLine: ${edit.args.EndLine}`);
        console.log(`TargetContent (first 100 chars):`, JSON.stringify(edit.args.TargetContent.substring(0, 100)));
        console.log(`ReplacementContent (first 100 chars):`, JSON.stringify(edit.args.ReplacementContent.substring(0, 100)));
      } else if (edit.name === 'multi_replace_file_content') {
        console.log(`Chunks: ${edit.args.ReplacementChunks.length}`);
        edit.args.ReplacementChunks.forEach((chunk, cIdx) => {
          console.log(`  Chunk #${cIdx + 1} | Start: ${chunk.StartLine} | End: ${chunk.EndLine}`);
          console.log(`  TargetContent (first 100 chars):`, JSON.stringify(chunk.TargetContent.substring(0, 100)));
          console.log(`  ReplacementContent (first 100 chars):`, JSON.stringify(chunk.ReplacementContent.substring(0, 100)));
        });
      } else if (edit.name === 'write_to_file') {
        console.log(`Written content length: ${edit.args.CodeContent.length}`);
      }
    });
  }
}

inspect();

