const fs = require('fs');
const path = require('path');

const filesToInspect = [
  'edits-Purchase.jsx.json',
  'edits-purchase.js.json',
  'edits-CSAMyInvoices.jsx.json',
  'edits-CSAMyPurchase.jsx.json',
  'edits-CSAMyBilling.jsx.json'
];

let output = '';
function log(msg) {
  output += msg + '\n';
}

function inspect() {
  for (const filename of filesToInspect) {
    const filePath = path.join(__dirname, filename);
    if (!fs.existsSync(filePath)) {
      continue;
    }
    const data = JSON.parse(fs.readFileSync(filePath, 'utf-8'));
    log(`======================================================`);
    log(`=== File: ${filename} (Total edits: ${data.length}) ===`);
    log(`======================================================`);

    data.forEach((edit, idx) => {
      log(`\n[Edit #${idx + 1}] Step: ${edit.step_index} | Type: ${edit.name}`);
      if (edit.name === 'replace_file_content') {
        log(`StartLine: ${edit.args.StartLine} | EndLine: ${edit.args.EndLine}`);
        log(`TargetContent:\n----------\n${edit.args.TargetContent || ''}\n----------`);
        log(`ReplacementContent:\n----------\n${edit.args.ReplacementContent || ''}\n----------`);
      } else if (edit.name === 'multi_replace_file_content') {
        log(`Chunks: ${edit.args.ReplacementChunks.length}`);
        edit.args.ReplacementChunks.forEach((chunk, cIdx) => {
          log(`  Chunk #${cIdx + 1} | Start: ${chunk.StartLine} | End: ${chunk.EndLine}`);
          log(`  TargetContent:\n----------\n${chunk.TargetContent || ''}\n----------`);
          log(`  ReplacementContent:\n----------\n${chunk.ReplacementContent || ''}\n----------`);
        });
      } else if (edit.name === 'write_to_file') {
        log(`Written content length: ${edit.args.CodeContent ? edit.args.CodeContent.length : 0}`);
      }
    });
  }

  fs.writeFileSync(path.join(__dirname, 'edits-report.txt'), output);
  console.log('Saved report to edits-report.txt');
}

inspect();
